{
  "requirement_definitions": [
    {
      "id": "DMSR-6199",
      "title": "Transparent Data Access",
      "text": "The DMS shall provide an interface that allows retrieval by productions or science users of datasets from any Facility where they may reside without requiring reconﬁguration."
    },
    {
      "id": "DMSR-9969",
      "title": "Level-1 Production Completeness",
      "text": "The DMS shall ensure that all images taken by the camera and marked for Level-1 processing are eventually retrieved, archived, and processed even in the event of connectivity failure between downstream Facilities."
    },
    {
      "id": "DMSR-1575",
      "title": "Calibration Images Available Within Speciﬁed Time",
      "text": "Calibration products from a group of up to nCalExpProc related exposures that should be processed together, shall be available from the DMS image archive within calProcTime of the end of the acquisition of images/data for that group."
    },
    {
      "id": "DMSR-6009",
      "title": "Transient Alert Distribution",
      "text": "Identiﬁed transient events shall be made available to end-users in the form of alerts, which shall be published to community alert distribution networks using communitystandard protocols, to be determined during the LSST construction phase as community standards evolve."
    },
    {
      "id": "DMSR-9975",
      "title": "Alert Stream Distribution",
      "text": "LSST shall be capable of supporting the transmission of at least numStreams full alert streams out of the alert distribution system within OTT1."
    },
    {
      "id": "DMSR-2810",
      "title": "Alert Delay and Failure Tolerances",
      "text": "The system shall reliably produce alerts for standard science visits read out in the camera [and speciﬁed to be analyzed by Data Management] such that no more than sciVisitAlertDelay per cent of visits will fail to have at least OTR1 per cent of its alerts distributed via the LSST alert distribution system within OTT1, and no more than sciVisitAlertFailure per cent of visits will fail to generate and distribute alerts (integrated over all stages of data handling)"
    },
    {
      "id": "DMSR-3454",
      "title": "Performance Requirements for Transient Alert Distribution",
      "text": "The system shall be able to identify and distribute an average of at least nAlertVisitAvg alerts per standard visit during a given night, and at least nAlertVisitPeak for a single standard visit.\nPerformance shall degrade gracefully beyond nAlertVisitAvg."
    }
  ],
  "allocation_entries": []
}
